export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/tilecov2
mkdir -p $D && cd $D || exit 1
cat > /tmp/tc2.b64 <<'B64EOF'

B64EOF
rm -rf ./* && base64 -d /tmp/tc2.b64 > /tmp/tc2.zip && unzip -oq /tmp/tc2.zip -d .
/opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source ./build.tcl > build.log 2>&1
if grep -q COV2_DONE build.log; then echo BUILD_OK; grep -E 'SITES=|Number of LUT|WNS' build.log | head -5; else echo BUILD_FAIL; grep -E 'ERROR' build.log | head -5; fi
tar czf /tmp/tilecov2_out.tgz cov2.bit cov2.pips build.log 2>/dev/null; echo TAR_DONE